    'euro_knockout_home_v1' => 'Match couperet :competition_de dans votre stade. Vous recevez :opponent_a : gagner ou tomber. Les soirées continentales ont quelque chose de spécial et les tribunes le savent.',
    'euro_knockout_home_v2_headline' => 'Duel à la vie à la mort face à :opponent_el',
    'euro_knockout_home_v2' => 'Duel européen à la vie à la mort face à :opponent_el à domicile. Aucune marge d\'erreur : un mauvais jour vous élimine de l\'Europe. La concentration doit être totale.',
    'euro_knockout_away_v1_headline' => 'Examen continental à l\'extérieur',
    'euro_knockout_away_v1' => 'Match couperet :competition_de à l\'extérieur. Vous visitez :opponent_a : gagner ou tomber. Ramener un bon résultat, c\'est la moitié de la qualification : l\'équipe voyage avec ambition.',
    'euro_knockout_away_v2_headline' => 'Aucune marge d\'erreur sur le terrain :opponent_de',
    'euro_knockout_away_v2' => 'Duel européen à la vie à la mort sur le terrain :opponent_de. Aucune marge d\'erreur. L\'adversaire est redoutable à domicile, mais cette équipe a déjà prouvé qu\'elle ne se dégonfle pas à l\'extérieur.',

    'euro_group_home_v1_headline' => 'Soirée :competition_de sous les projecteurs',
    'euro_group_home_v1' => 'Soirée :competition_de sous les projecteurs. Vous recevez :opponent_a avec le continent en jeu et la nécessité de prendre des points pour ne pas compliquer la qualification. L\'hymne retentira et la chair de poule sera au rendez-vous.',
    'euro_group_home_v2_headline' => ':competition_el est de retour dans votre stade',
    'euro_group_home_v2' => ':competition_el est de retour dans votre stade : vous recevez :opponent_a. Les points à domicile ne sont pas négociables si on veut passer ce tour.',
    'euro_group_away_v1_headline' => 'Déplacement européen face à :opponent_el',
    'euro_group_away_v1' => 'Soirée :competition_de à l\'extérieur. Vous visitez :opponent_a sous les projecteurs, dans un stade qui pousse. Prendre des points à l\'extérieur, c\'est toujours de l\'or en phase de groupes.',
    'euro_group_away_v2_headline' => 'Duel continental à l\'extérieur',
    'euro_group_away_v2' => 'Duel européen à l\'extérieur face à :opponent_el en :competition_el. Le voyage est long et l\'adversaire exigeant : il faudra la meilleure version de l\'équipe.',

    // ── Rivalité et Face à face ─────────────────────────────────────

    'rivalry_won_reverse_v1_headline' => 'Vous avez déjà battu :opponent_a :score : à refaire',
    'rivalry_won_reverse_v1' => 'Vous avez battu :opponent_a :score au match aller. À refaire : l\'adversaire cherchera sa revanche et sortira le couteau entre les dents. Pas d\'excès de confiance.',
    'rivalry_won_reverse_v2_headline' => 'Le dernier duel a tourné en votre faveur',
    'rivalry_won_reverse_v2' => 'Le dernier duel a tourné en votre faveur (:score face à :opponent_el). Le moral est haut, mais les précédents ne jouent pas : chaque match repart de zéro.',

    'rivalry_lost_reverse_v1_headline' => 'L\'heure de la revanche face à :opponent_el',
    'rivalry_lost_reverse_v1' => ':Opponent_el a gagné l\'aller :score. L\'heure de la revanche a sonné : le vestiaire a cette défaite en travers de la gorge, et les tribunes aussi. Les derbys émotionnels se gagnent la tête froide.',
    'rivalry_lost_reverse_v2_headline' => 'Comptes à régler avec :opponent_el',
    'rivalry_lost_reverse_v2' => 'Il y a des comptes à régler : :opponent_el a pris les points :score la dernière fois. Le staff technique a décortiqué ce match jusqu\'à l\'écœurement : les mêmes erreurs ne se répéteront pas.',

    'rivalry_drew_reverse_v1_headline' => 'Faire pencher la balance face à :opponent_el',
    'rivalry_drew_reverse_v1' => 'Match nul avec :opponent_el à l\'aller. L\'occasion de faire pencher la balance dans un duel qui, historiquement, se décide sur des détails. L\'ambition doit l\'emporter sur le respect.',
    'rivalry_drew_reverse_v2_headline' => 'Briser l\'égalité face à :opponent_el',
    'rivalry_drew_reverse_v2' => 'Le duel aller avec :opponent_el s\'est terminé sur un nul — brisez l\'égalité. Ce sont deux équipes de niveau égal et le match se décidera dans les surfaces.',

    // ── Marché des transferts ───────────────────────────────────────

    'market_courted_v1_headline' => ':Club_el passe à l\'action pour :player',
    'market_courted_v1' => ':Club_el est passé à l\'action pour :player. Attention au vestiaire : ces rumeurs distraient, et la joueuse devra faire preuve de professionnalisme. Le club, pour l\'instant, se retranche derrière la clause.',
    'market_courted_v2_headline' => 'La spéculation enfle autour de :player',
    'market_courted_v2' => 'La spéculation enfle autour de :player avec l\'intérêt :club_de. Son agent ne dément rien, ce qui alimente les rumeurs. Les supporters croisent les doigts.',
    'market_courted_v3_headline' => 'Rumeurs : :player sur les tablettes :club_de',
    'market_courted_v3' => 'Les rumeurs lient :player à :club_el. Pour l\'instant, aucune offre formelle sur la table, mais il n\'y a pas de fumée sans feu... Le marché s\'échauffe.',

    'market_precontract_v1_headline' => ':Club_el rôde autour de :player pour un pré-contrat',
    'market_precontract_v1' => ':Club_el rôde autour de :player pour un pré-contrat. Son avenir est en suspens et le club risque de la perdre à coût zéro. La prolongation devrait être prioritaire.',
    'market_precontract_v2_headline' => ':Club_el tâte le terrain pour :player : inquiétude',
    'market_precontract_v2' => ':Club_el tâte le terrain pour :player — des nouvelles qui inquiètent. Sans prolongation rapide, la joueuse pourra négocier librement. La direction sportive a du pain sur la planche.',
    'market_precontract_v3_headline' => 'Pré-contrat à l\'horizon pour :player',
    'market_precontract_v3' => ':Club_el préparerait une offre de pré-contrat pour :player. Le temps joue contre le club : chaque semaine sans prolongation fait baisser le prix d\'un éventuel transfert.',

    'market_multiple_targets_v1_headline' => 'Les vautours rôdent : :count joueuses en vitrine',
    'market_multiple_targets_v1' => 'Les vautours rôdent : :count de vos joueuses suscitent l\'intérêt du marché. Avoir autant de footballeuses cotées est bon signe, mais les retenir sera la grande bataille de l\'été.',
    'market_multiple_targets_v2_headline' => ':count footballeuses courtisées',
    'market_multiple_targets_v2' => ':count footballeuses sont courtisées. Le marché met votre sang-froid à l\'épreuve : bien vendre, c\'est aussi bien recruter, mais les supporters ne pardonneraient pas un démantèlement.',

    'market_window_closing_v1_headline' => 'Le marché ferme ses portes : dernières heures',
    'market_window_closing_v1' => 'Le marché est sur le point de fermer — dernière occasion pour agir. Les téléphones chauffent dans les bureaux et des mouvements de dernière minute sont attendus. Que personne ne s\'endorme.',
    'market_window_closing_v2_headline' => 'Fermeture du marché imminente',
    'market_window_closing_v2' => 'La fermeture guette. Le marché ferme dans quelques journées et des dossiers restent ouverts sur la table. La direction sportive boucle les dernières démarches.',

    // ── Tournoi : Phase de groupes ──────────────────────────────────

    'wc_group_opener_v1_headline' => 'Débuts au Mondial : bien commencer',
    'wc_group_opener_v1' => 'Match inaugural du Mondial. Une belle occasion de bien commencer et de mettre la pression sur le reste du groupe. Les débuts apportent toujours de la nervosité : l\'équipe qui la gérera le mieux frappera la première.',
    'wc_group_opener_v2_headline' => 'Le tournoi démarre : trois points en or',
    'wc_group_opener_v2' => 'Premier match du tournoi. Trois points ici seraient un excellent début et changeraient complètement le paysage du groupe. La préparation a été longue : il est temps de le prouver.',
    'wc_group_opener_v3_headline' => 'LE RIDEAU SE LÈVE',
    'wc_group_opener_v3' => 'L\'aventure mondialiste commence. Le vestiaire rêve de ce moment depuis des mois et le pays entier se fige. Que le spectacle commence.',

    'wc_group_must_win_v1_headline' => 'Seule la victoire compte',
    'wc_group_must_win_v1' => 'Dernier match de groupe. Seule la victoire compte : les comptes sont clairs et il n\'y a pas de plan B. L\'équipe devra prendre des risques dès le début, quitte à laisser des espaces derrière.',
    'wc_group_must_win_v2_headline' => 'Victoire obligatoire pour rester en vie',
    'wc_group_must_win_v2' => 'Victoire obligatoire pour garder les chances de qualification. La pression est maximale, mais ce sont ces matches qui forgent les grandes sélections.',
    'wc_group_must_win_v3_headline' => 'FINALE AVANT L\'HEURE',
    'wc_group_must_win_v3' => 'Sans victoire, les valises à l\'aéroport. Le vestiaire le sait et les supporters aussi : aujourd\'hui, pas de calculs. À fond dès la première minute.',

    'wc_group_top_v1_headline' => 'En tête du Groupe :group',
    'wc_group_top_v1' => 'En tête du Groupe :group. La qualification dépend de vous : gagner aujourd\'hui scellerait presque le passage en tant que premières. Le sélectionneur demande de ne pas se relâcher.',
    'wc_group_top_v2_headline' => 'Premières du Groupe :group',
    'wc_group_top_v2' => 'Premières du Groupe :group avant le prochain match. La dynamique est positive et le vestiaire est uni. Garder la première place offrirait un tirage plus favorable.',
    'wc_group_top_v3_headline' => 'PATRONNES DU GROUPE',
    'wc_group_top_v3' => 'Têtes de série du Groupe :group. Le tournoi, pour l\'instant, sourit : continuer à engranger pour choisir son adversaire en huitièmes.',

    'wc_group_qualified_v1_headline' => 'Qualifiées : cap sur la première place',
    'wc_group_qualified_v1' => 'Déjà qualifiées pour la phase à élimination directe. Reste à viser la première place, qui évite les gros morceaux au tirage. Des rotations sont attendues, mais personne ne veut perdre la dynamique.',
    'wc_group_qualified_v2_headline' => 'Billet validé : un match pour prendre le rythme',
    'wc_group_qualified_v2' => 'Qualification assurée. Ce match est pour prendre le rythme et donner des minutes aux moins utilisées. L\'objectif : arriver en huitièmes avec tout le groupe dans le coup.',
    'wc_group_qualified_v3_headline' => 'BILLET VALIDÉ',
    'wc_group_qualified_v3' => 'Cap sur la première place du groupe. Le travail bien fait lors des deux premières journées permet d\'aborder ce match sans pression : un luxe dans un Mondial.',

    'wc_group_on_brink_v1_headline' => 'La qualification à portée de main',
    'wc_group_on_brink_v1' => 'La qualification est proche. Un bon résultat pourrait suffire et le vestiaire fait ses comptes depuis des jours. Mieux vaut ne pas dépendre des autres : à la sceller aujourd\'hui.',
    'wc_group_on_brink_v2_headline' => 'Un point pourrait suffire',
    'wc_group_on_brink_v2' => 'Proches de la phase à élimination directe. Un point aujourd\'hui pourrait la sceller, mais jouer le nul coûte souvent cher. Le plan : jouer pour gagner comme toujours.',
    'wc_group_on_brink_v3_headline' => 'À UN PAS',
    'wc_group_on_brink_v3' => 'Un nul pourrait suffire pour passer. La calculette chauffe dans les tribunes, mais sur le terrain une seule chose compte : rivaliser.',

    'wc_group_eliminated_v1_headline' => 'Dernière danse dans le tournoi',
    'wc_group_eliminated_v1' => 'La qualification n\'est plus possible. Reste un dernier match à disputer avec dignité pour quitter le tournoi la tête haute. Les jeunes auront des minutes.',
    'wc_group_eliminated_v2_headline' => 'Terminer la phase de groupes avec honneur',
    'wc_group_eliminated_v2' => 'Hors course, mais il reste un match pour clore la phase de groupes. L\'orgueil est en jeu et le sélectionneur veut voir du caractère.',
    'wc_group_eliminated_v3_headline' => 'FIN DU RÊVE',
    'wc_group_eliminated_v3' => 'Dernière danse en phase de groupes. Le tournoi ne s\'est pas passé comme prévu, mais le maillot se défend jusqu\'au bout.',

    'wc_group_gd_v1_headline' => 'La différence de buts peut décider',
    'wc_group_gd_v1' => 'La différence de buts pourrait être décisive. Groupe très serré où chaque but compte double. Le sélectionneur a déjà prévenu : si c\'est possible, il faut cartonner.',
    'wc_group_gd_v2_headline' => 'Groupe serré : chaque but compte',
    'wc_group_gd_v2' => 'Groupe serré. La différence de buts peut finir par départager les équipes, alors pas question de lever le pied même avec le match plié.',
    'wc_group_gd_v3_headline' => 'LA CALCULETTE EN MAIN',
    'wc_group_gd_v3' => 'La différence de buts pourrait décider du groupe. Les égalités de points se départagent aux buts : chaque but peut valoir une qualification.',

    // ── Tournoi : Phase à élimination directe ────────────────────────

    'wc_knockout_r32_v1_headline' => 'Seizièmes de finale : aucune marge d\'erreur',
    'wc_knockout_r32_v1' => 'Seizièmes de finale. Élimination directe, aucune marge d\'erreur : un mauvais jour et c\'est le retour à la maison. La tension est palpable dès l\'hymne.',
    'wc_knockout_r32_v2_headline' => 'Les choses sérieuses commencent : gagner ou rentrer',
    'wc_knockout_r32_v2' => 'La phase à élimination directe commence. Une défaite ici signifie la fin du tournoi, l\'approche sera donc d\'une prudence maximale. Les détails décident.',
    'wc_knockout_r32_v3_headline' => 'À LA VIE À LA MORT',
    'wc_knockout_r32_v3' => 'La phase à élimination directe commence. Quatre-vingt-dix minutes — ou cent vingt — pour continuer à rêver. Il n\'y a pas de lendemain.',

    'wc_knockout_r16_v1_headline' => 'Huitièmes de finale : il en reste 16',
    'wc_knockout_r16_v1' => 'Huitièmes de finale. Seize sélections sont encore en compétition et le niveau est déjà très élevé. Survivre ici est l\'affaire des grandes équipes.',
    'wc_knockout_r16_v2_headline' => 'Parmi les 16 dernières du monde',
    'wc_knockout_r16_v2' => 'Parmi les 16 dernières. Le niveau des adversaires monte à partir d\'ici et la moindre inattention se paie très cher. L\'expérience de ces rendez-vous sera clé.',
    'wc_knockout_r16_v3_headline' => 'IL EN RESTE 16',
    'wc_knockout_r16_v3' => 'Huitièmes de finale du Mondial. Le tournoi se resserre et seules les meilleures survivent.',

    'wc_knockout_qf_v1_headline' => 'Quarts : à trois matches du titre',
    'wc_knockout_qf_v1' => 'Vous êtes en quarts de finale. Seuls trois matches vous séparent du titre mondial. Le vestiaire le sait et l\'enthousiasme déborde, mais le plus dur reste à faire.',
    'wc_knockout_qf_v2_headline' => 'Parmi les huit meilleures : les demies en jeu',
    'wc_knockout_qf_v2' => 'Parmi les huit meilleures. En jeu, une place en demi-finales, où l\'histoire attend déjà. L\'adversaire fait partie de ceux qui font peur, mais à ce stade, ils le font tous.',
    'wc_knockout_qf_v3_headline' => 'TERRITOIRE D\'ÉLITE',
    'wc_knockout_qf_v3' => 'Il ne reste que huit sélections dans le tournoi. Chaque match à partir de maintenant est une finale avant l\'heure.',

    'wc_knockout_sf_v1_headline' => 'Demi-finale : gagner, c\'est jouer la finale',
    'wc_knockout_sf_v1' => 'Demi-finale. Gagner aujourd\'hui signifie jouer la finale du Mondial. Le pays se fige et le vestiaire prépare ce moment depuis toujours. Que le pouls ne tremble pas.',
    'wc_knockout_sf_v2_headline' => 'À un match de la finale',
    'wc_knockout_sf_v2' => 'À un match de la finale. Le rendez-vous le plus important du tournoi jusqu\'ici, sauf ce qui viendra après. La gestion émotionnelle sera décisive.',
    'wc_knockout_sf_v3_headline' => 'AUX PORTES DE LA FINALE',
    'wc_knockout_sf_v3' => 'Quatre-vingt-dix minutes pour entrer dans l\'histoire. La finale est si proche qu\'on peut presque la toucher.',

    'wc_knockout_third_v1_headline' => 'Le bronze en jeu',
    'wc_knockout_third_v1' => 'Match pour la troisième place. Il reste une médaille en jeu et la fierté de terminer le tournoi sur le podium. Ne pas être en finale fait mal, mais une médaille, c\'est pour toujours.',
    'wc_knockout_third_v2_headline' => 'Cap sur le bronze la tête haute',
    'wc_knockout_third_v2' => 'Le match pour le bronze. L\'occasion de terminer sur une note positive un tournoi au goût d\'inachevé. Le sélectionneur donnera des minutes à celles qui ont le moins joué.',
    'wc_knockout_third_v3_headline' => 'LE LOT DE CONSOLATION',
    'wc_knockout_third_v3' => 'Mais une médaille est une médaille. La troisième place se fête moins, mais on s\'en souvient toujours.',

    'wc_knockout_final_v1_headline' => 'LA FINALE DU MONDIAL',
    'wc_knockout_final_v1' => 'La finale du Mondial. Le dernier match du tournoi, celui que la planète entière regardera. Quatre-vingt-dix minutes pour l\'immortalité : les noms des championnes restent à jamais.',
    'wc_knockout_final_v2_headline' => 'Un match pour décider du champion',
    'wc_knockout_final_v2' => 'La finale. Un match pour décider du champion du monde. Tout ce qui précède — des années de travail, de sacrifices — mène à cette nuit.',
    'wc_knockout_final_v3_headline' => 'LE MATCH',
    'wc_knockout_final_v3' => 'La finale du monde. Il n\'y a pas de mots : il ne reste qu\'à la jouer.',

    // ── Tournoi : Contexte de l'adversaire ──────────────────────────

    'wc_opponent_group_leader_v1_headline' => ':opponent, leader du groupe : examen exigeant',
    'wc_opponent_group_leader_v1' => ':opponent mène le groupe. Un match exigeant sur le papier face à la sélection la plus en forme du groupe. Prendre des points ici aurait une valeur double.',
    'wc_opponent_group_leader_v2_headline' => 'L\'épouvantail du groupe : :opponent',
    'wc_opponent_group_leader_v2' => ':opponent est premier du groupe. Un bon thermomètre pour mesurer les ambitions réelles dans le tournoi.',
    'wc_opponent_group_leader_v3_headline' => 'L\'ÉPOUVANTAIL DU GROUPE',
    'wc_opponent_group_leader_v3' => ':opponent domine le classement. Personne n\'a pu les battre jusqu\'ici : être les premières serait un coup d\'autorité.',

    'wc_opponent_group_bottom_v1_headline' => ':opponent, lanterne rouge : match piège',
    'wc_opponent_group_bottom_v1' => ':opponent est dernier du groupe. Pourtant, à ce niveau, rien n\'est simple : elles jouent sans pression et cela les rend dangereuses. Interdiction de se relâcher.',
    'wc_opponent_group_bottom_v2_headline' => 'Cendrillon du groupe, mais avec fierté',
    'wc_opponent_group_bottom_v2' => ':opponent est lanterne rouge du groupe sur le papier, mais dans un tournoi la forme est imprévisible. Elles voudront partir avec dignité.',
    'wc_opponent_group_bottom_v3_headline' => 'CENDRILLON DU GROUPE',
    'wc_opponent_group_bottom_v3' => ':opponent n\'a rien à perdre. Et les équipes qui n\'ont rien à perdre sont les plus dangereuses.',

    'wc_opponent_tournament_streak_v1_headline' => ':opponent, avec un sans-faute',
    'wc_opponent_tournament_streak_v1' => ':opponent a gagné tous ses matches du tournoi jusqu\'ici. La sélection la plus en forme du championnat : les stopper serait la sensation du Mondial.',
    'wc_opponent_tournament_streak_v2_headline' => ':opponent, invaincue : adversaire très compliqué',
    'wc_opponent_tournament_streak_v2' => ':opponent est invaincue dans la compétition. Un adversaire compliqué qui ne connaît pas la défaite dans ce tournoi. Il faudra un match parfait.',
    'wc_opponent_tournament_streak_v3_headline' => 'INTRAITABLE',
    'wc_opponent_tournament_streak_v3' => ':opponent arrive avec un sans-faute. Le favoritisme est pour elles, mais les favoris tombent aussi.',

    'wc_opponent_winless_v1_headline' => ':opponent, toujours sans victoire : blessée et dangereuse',
    'wc_opponent_winless_v1' => ':opponent n\'a toujours pas gagné dans ce tournoi. Elles arrivent blessées avec le besoin de sauver leur image : exactement le type d\'adversaire qui gâche la fête.',
    'wc_opponent_winless_v2_headline' => ':opponent cherche sa première victoire',
    'wc_opponent_winless_v2' => ':opponent vit un tournoi difficile jusqu\'ici. Elles voudront inverser la dynamique et n\'ont rien à perdre.',
    'wc_opponent_winless_v3_headline' => 'BLESSÉES ET DANGEREUSES',
    'wc_opponent_winless_v3' => ':opponent cherche toujours sa première victoire. L\'orgueil blessé multiplie le danger.',

    // ── Tournoi : Ambiance ──────────────────────────────────────────

    'wc_weather_v1_headline' => 'La chaleur, facteur du match',
    'wc_weather_v1' => 'De fortes chaleurs sont attendues. La chaleur pourrait être un facteur : la gestion des efforts et les pauses hydratation seront clés. L\'équipe qui la gérera le mieux aura un avantage.',
    'wc_weather_v2_headline' => 'Humidité et chaleur : match d\'endurance',
    'wc_weather_v2' => 'Conditions chaudes en Amérique du Nord. La forme physique et l\'hydratation compteront autant que la tactique. De nombreux changements sont attendus en seconde période.',
    'wc_weather_v3_headline' => 'ALERTE CANICULE',
    'wc_weather_v3' => 'Prévision d\'humidité et de températures élevées. Le match pourrait se décider dans le dernier tronçon, quand les jambes seront lourdes.',

    'wc_fans_v1_headline' => 'Tribunes pleines : ambiance de gala',
    'wc_fans_v1' => 'Un stade plein est attendu. Belle ambiance prévue, avec des supporters acquis qui pousseront dès l\'échauffement. Jouer soutenue aide toujours.',
    'wc_fans_v2_headline' => 'Des millions d\'yeux rivés sur le match',
    'wc_fans_v2' => 'Des millions de téléspectateurs dans le monde entier. Un grand rendez-vous pour les deux équipes et une vitrine idéale pour les joueuses.',
    'wc_fans_v3_headline' => 'FÊTE DANS LES TRIBUNES',
    'wc_fans_v3' => 'Le Mondial attire un public unique. Couleurs, bruit et émotion : le football féminin vit sa grande fête.',

    'wc_media_v1_headline' => 'Projecteurs médiatiques sur le match',
    'wc_media_v1' => 'Beaucoup d\'attention médiatique sur ce match. Une rencontre de haut niveau qui ouvre les journaux télévisés dans la moitié du monde. Les protagonistes sont prévenues : chaque geste compte.',
    'wc_media_v2_headline' => 'La presse internationale aux aguets',
    'wc_media_v2' => 'Presse internationale pour couvrir le match. Les projecteurs sont braqués et les stars devront performer sous les feux les plus exigeants.',

    'wc_group_color_v1_headline' => 'La phase de groupes trace la route',
    'wc_group_color_v1' => 'La phase de groupes est lancée. Les résultats ici tracent la route : un bon départ simplifie tout le reste.',
